// oracle.mjs — port of dat/oracle.lua (Delphi, the Oracle level).
//
// Generated by mkmaze.c makemaz() on one level of Dlvl 5-9 in every game, so
// it is reachable from essentially any session that goes below Dlvl 4.
//
// Ported 1:1 from the Lua. The only randomness is inside the C bindings
// themselves (des.monster()/des.object()/des.trap() with no arguments pick a
// random species/type/spot; des.room() with no geometry picks a random room),
// so equivalence here is exactly "the same des.* calls in the same order with
// the same arguments" — which is what makes this the right first port.
//
// Original: nethack-c/recorder/dat/oracle.lua
//   $NHDT-Date: 1652196033 2022/05/10 15:20:33 $
//   Copyright (c) 2015 by Pasi Kallinen. NetHack may be freely redistributed.

/** @param {{des: object}} api */
export default function oracle({ des }) {
    des.level_flags('noflip');

    des.room({
        type: 'ordinary', lit: 1, x: 3, y: 3,
        xalign: 'center', yalign: 'center', w: 11, h: 9,
        contents: () => {
            des.object({ id: 'statue', x: 0, y: 0, montype: 'C', historic: true });
            des.object({ id: 'statue', x: 0, y: 8, montype: 'C', historic: true });
            des.object({ id: 'statue', x: 10, y: 0, montype: 'C', historic: true });
            des.object({ id: 'statue', x: 10, y: 8, montype: 'C', historic: true });
            des.object({ id: 'statue', x: 5, y: 1, montype: 'C', historic: true });
            des.object({ id: 'statue', x: 5, y: 7, montype: 'C', historic: true });
            des.object({ id: 'statue', x: 2, y: 4, montype: 'C', historic: true });
            des.object({ id: 'statue', x: 8, y: 4, montype: 'C', historic: true });

            des.room({
                type: 'delphi', lit: 1, x: 4, y: 3, w: 3, h: 3,
                contents: () => {
                    des.feature('fountain', 0, 1);
                    des.feature('fountain', 1, 0);
                    des.feature('fountain', 1, 2);
                    des.feature('fountain', 2, 1);
                    des.monster('Oracle', 1, 1);
                    des.door({ state: 'nodoor', wall: 'all' });
                },
            });

            des.monster();
            des.monster();
        },
    });

    des.room({
        contents: () => {
            des.stair('up');
            des.object();
        },
    });

    des.room({
        contents: () => {
            des.stair('down');
            des.object();
            des.trap();
            des.monster();
            des.monster();
        },
    });

    des.room({
        contents: () => {
            des.object();
            des.object();
            des.monster();
        },
    });

    des.room({
        contents: () => {
            des.object();
            des.trap();
            des.monster();
        },
    });

    des.room({
        contents: () => {
            des.object();
            des.trap();
            des.monster();
        },
    });

    des.random_corridors();
}
